import{z as d,x as i,o as t,c as l,q as o,j as c,D as a,d as r,s as n,S as E}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"协议栈的调试工具","description":"","frontmatter":{"title":"协议栈的调试工具","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/npk-debugging-tools.md","filePath":"cs/npk-debugging-tools.md","lastUpdated":1791063341000}'),p={name:"cs/npk-debugging-tools.md"};function A(B,e,k,_,h,f){const s=i("Mermaid");return t(),l("div",null,[e[2]||(e[2]=o('<h1 id="协议栈的调试工具" tabindex="-1">协议栈的调试工具 <a class="header-anchor" href="#协议栈的调试工具" aria-label="Permalink to &quot;协议栈的调试工具&quot;">​</a></h1><div class="epigraph"><p>排障的纪律是先问「丢在哪一层」，再问「为什么丢」；工具不是按名字挑的，是按你要看的那节管道挑的。</p><footer>—— 据 Linux ss/nstat/ethtool 手册；内核 per-cpu 计数器与 sock_diag 文档整理</footer></div><p><a href="/cs/npk-socket-layer">上一课</a>把 fd 与 sock 的映射钉死，也留了一句伏笔：<code>ss</code> 这类工具靠 <code>AF_NETLINK</code> 直接读内核的 sock 对象。前三课还埋了更重要的东西——一整条路径上<strong>每层的计数器</strong>：网卡的环、软中断的预算、backlog、socket 队列、TCP 子状态。<a href="/cs/packet-capture">抓包与 Wireshark</a> 教过线上的对证，<a href="/cs/osk-kernel-debugging">内核调试的方法</a>教过 ftrace 与 kprobe 的分工。本课把工具按「症状在哪层」重排：从吞吐异常或连接卡死出发，走到具体哪一节管道出了问题。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>协议栈排障的缺口不是缺工具，而是计数器太多、彼此独立，按名字扫一遍什么也读不出来。必须先有一个从症状到层的判定序。不这么做会错在哪：只看 <code>ifconfig</code> 的总错包数——收包环、协议栈、应用层不读的丢包都混在 error 计数里，读不出丢在哪层；一上来就 <code>tcpdump</code> 抓全量——生产机上 CPU 与磁盘先饱和，且抓到的只是协议叙事，回答不了「包根本没到」；对 <code>netstat -s</code> 的绝对值惊慌——这些计数器从开机累加，不看增量与对照等于没看。</p><p><span class="marginnote">常见误区：看到 <code>netstat -s</code> 里「X 万个包被丢弃」就断定正在丢包。这些计数器从开机一路累加——一台跑了半年的机器，历史累计可能早就数以万计，而此刻的丢弃速率是零。正确读法是隔几秒取两次快照做差：差值为正且与症状同步增长，才算证据。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>按层走一遍判定序。第一层，包到没到网卡：<code>ethtool -S</code> 看驱动的 <code>rx_missed_errors</code>、<code>rx_no_buffer</code>——环或缓冲耗尽，包死在 DMA 之后、内核之前。第二层，进没进协议栈：<code>/proc/net/softnet_stat</code> 每行头三列是已处理数、软中断内丢弃数、<code>time_squeeze</code>（预算用尽次数，十六进制）；第四列起是 backlog 溢出与 CPU 忙不过来的挤兑记录。第三层，TCP 在哪丢：<code>nstat</code> 读 TcpExt——<code>ListenOverflows</code>/<code>ListenDrops</code> 对应 <a href="/cs/npk-tcp-state-machine">accept 队列满</a>，<code>TCPBacklogDrop</code> 对应 <a href="/cs/npk-rx-path">软中断与进程上下文的交接</a>，<code>PruneCalled</code> 是 socket 内存会计在修剪队列。第四层，看单个连接：<code>ss -tinp</code> 经 sock_diag 直接读内核 sock——state、cwnd、rtt、重传数，把<a href="/cs/npk-congestion-implementation">拥塞子状态机</a>的变量按连接打印出来。最后才抓包，且只抓四元组过滤后的流量，按<a href="/cs/packet-capture">捕获点纪律</a>注意 GRO 与卸载对边界的变形。静态计数器答不了的时序问题，用 <a href="/cs/ebpf-observability">BPF 观测</a>在事件处聚合，或按 <a href="/cs/osk-kernel-debugging">ftrace 的分工</a>用 tracepoint 取稳定字段。</p>',8)),(t(),c(E,null,{default:a(()=>[n(s,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20SYM%5B%22%E7%97%87%E7%8A%B6%EF%BC%9A%E6%85%A2%20%2F%20%E5%8D%A1%20%2F%20%E4%B8%A2%22%5D%20--%3E%20L1%7B%22ethtool%20-S%EF%BC%9A%E7%8E%AF%E4%B8%A2%E6%B2%A1%E4%B8%A2%3F%22%7D%0A%20%20L1%20--%3E%7C%22%E6%B2%A1%E4%B8%A2%22%7C%20L2%7B%22softnet_stat%EF%BC%9A%E8%BD%AF%E4%B8%AD%E6%96%AD%E6%8C%A4%E5%85%91%3F%22%7D%0A%20%20L2%20--%3E%7C%22%E6%AD%A3%E5%B8%B8%22%7C%20L3%7B%22nstat%EF%BC%9ATCP%20%E5%B1%82%E4%B8%A2%E5%8C%85%E8%AE%A1%E6%95%B0%3F%22%7D%0A%20%20L3%20--%3E%7C%22%E5%AE%9A%E4%BD%8D%E5%88%B0%E7%B1%BB%22%7C%20L4%5B%22ss%20-tinp%EF%BC%9A%E9%80%90%E8%BF%9E%E6%8E%A5%E7%9C%8B%E7%8A%B6%E6%80%81%E4%B8%8E%E7%AA%97%E5%8F%A3%22%5D%0A%20%20L4%20--%3E%20CAP%5B%22%E5%9B%9B%E5%85%83%E7%BB%84%E6%8A%93%E5%8C%85%E5%AF%B9%E8%AF%81%22%5D%0A%20%20CAP%20--%3E%20FIX%5B%22%E5%AE%9A%E4%BD%8D%E4%BF%AE%E5%A4%8D%22%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[r(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=o('<p><span class="marginnote">术语翻译：四元组就是（源 IP，源端口，目的 IP，目的端口）这四个数——一台机器上百万条连接全靠它区分。<code>time_squeeze</code> 直译「时间被挤掉」：软中断一次预算（比如 8 个包或一小段时间）用完了还没处理完，被迫收工的次数——它涨，说明 CPU 忙不过来，不是网卡丢。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>这些工具能工作，靠的是前几课埋下的结构：每层入口都有计数器，是实现的副产品；<code>ss</code> 能逐连接读 sock，是因为<a href="/cs/npk-socket-layer">套接字层</a>把 sock 做成了可寻址对象，netlink sock_diag 只是给它们开了查询口；softnet_stat 的三列对应<a href="/cs/npk-rx-path">软中断预算</a>的三个结果——处理完、丢掉、被挤兑。读懂机制还给了推断力：<code>time_squeeze</code> 持续增长而网卡干净，说明 CPU 是瓶颈，调大预算只是把拥塞从软中断挪到硬中断；<code>ListenDrops</code> 增长而应用 idle，说明 accept 循环跟不上，病在应用线程不在内核。</p><p><span class="marginnote">softnet_stat 头三列是 processed、dropped、time_squeeze，十六进制——把它当十进制读，结论会差一个数量级。<code>nstat -az</code> 加 <code>a</code> 才显示零值计数器；对比两次快照看增量，是这套计数器唯一的正确读法。</span></p><p><span class="marginnote">直觉类比：<code>ss</code> 查连接像去医院调病历——不是把病人搬出来，而是凭挂号号（四元组）到档案室（内核 sock 表）调阅化验单（state、cwnd、rtt、重传数）。netlink sock_diag 就是那扇「调阅窗口」：数据始终在内核里，用户态拿到的只是副本。</span></p>',5)),(t(),c(E,null,{default:a(()=>[n(s,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20U%5B%22%E7%94%A8%E6%88%B7%E6%89%A7%E8%A1%8C%20ss%20-tinp%22%5D%20--%3E%20NL%5B%22AF_NETLINK%20%E5%8F%91%E9%80%81%20sock_diag%20%E8%AF%B7%E6%B1%82%22%5D%0A%20%20NL%20--%3E%20K%5B%22%E5%86%85%E6%A0%B8%E6%8C%89%E5%9B%9B%E5%85%83%E7%BB%84%E6%9F%A5%20sock%20%E5%93%88%E5%B8%8C%E8%A1%A8%22%5D%0A%20%20K%20--%3E%20S%5B%22%E9%80%90%E4%B8%AA%20sock%20%E8%AF%BB%E5%AD%97%E6%AE%B5%22%5D%0A%20%20S%20--%3E%20F1%5B%22state%3A%20%E5%8D%8F%E8%AE%AE%E7%8A%B6%E6%80%81%22%5D%0A%20%20S%20--%3E%20F2%5B%22cwnd%20%2F%20rtt%3A%20%E6%8B%A5%E5%A1%9E%E4%B8%8E%E5%BB%B6%E8%BF%9F%22%5D%0A%20%20S%20--%3E%20F3%5B%22%E9%87%8D%E4%BC%A0%E6%95%B0%3A%20%E4%B8%A2%E5%8C%85%E7%BA%BF%E7%B4%A2%22%5D%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[r(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=o('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不重教过滤器语法与 Wireshark 用法（<a href="/cs/packet-capture">抓包与 Wireshark</a>），不重写 ftrace/kprobe 本体与 kdump（<a href="/cs/osk-kernel-debugging">内核调试的方法</a>），火焰图与硬件计数器归观测课，ns-3 一类仿真归<a href="/cs/network-simulation">网络仿真</a>。丢包原因编号（内核 5.17 起随 kfree_skb 事件给出 reason）按内核版本而定，判定序本身不随版本变。下一课收束全课程。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>排障按层走判定序：网卡环 → 软中断预算 → TCP 层计数 → 逐连接 sock → 抓包对证。</li><li>计数器从开机累加，只有增量与分层对照能当证据。</li><li><code>ss -tinp</code> 经 netlink 直接读内核 sock，是前三课对象账的查询口。</li><li>时序问题交给 BPF/tracepoint，捕获点与变形纪律照旧。</li><li>出处：Linux ss/nstat/ethtool 手册；内核 softnet_stat、TcpExt 与 sock_diag 文档口径整理。</li></ul>',4))])}const m=d(p,[["render",A]]);export{g as __pageData,m as default};
